#!/bin/bash
# Small end-to-end example: TPC-H at scale factor 0.01 (generated by DuckDB),
# 600 queries, 2 seeds. Takes about 30 seconds on 4 cores.
set -e
cd "$(dirname "$0")/.."
for seed in 1 2; do
  python src/pipeline.py --bench tpch --sf 0.01 --seed $seed \
    --n-queries 600 --splits 300:150:150 --workers 4 --worker-threads 1 \
    --n-inject 0 --data-dir data --out-dir results/example
done
python src/report.py results/example/tpch_sf0.01_leftdeep_mlp_seed*.json
